import Foundation
import XCTest

// Host tests of the registration-date estimate, compiled together with Sources/Model and
// Sources/Estimate only (pure Foundation). GGRegDateEstimateFixture.swift is generated by
// Data/generate.py next to the table.
//
// Without Bazel (macOS host):
//   xcrun swiftc -emit-library -Xlinker -bundle -module-name GGRegDateEstimateTests \
//     -F "$(xcrun --show-sdk-platform-path)/Developer/Library/Frameworks" \
//     -Xlinker -rpath -Xlinker "$(xcrun --show-sdk-platform-path)/Developer/Library/Frameworks" \
//     Sources/Model/*.swift Sources/Estimate/*.swift Tests/*.swift -o /tmp/GGRegDate.xctest
//   xcrun xctest /tmp/GGRegDate.xctest

final class GGRegDateEstimateTests: XCTestCase {
    private let day: Int64 = 86400
    private var now: Int32 { Int32(GGRegDateAnchors.dataEnd) }

    private func utc(_ year: Int, _ month: Int, _ day: Int, _ hour: Int = 0, _ minute: Int = 0, _ second: Int = 0) -> Int64 {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "UTC")!
        let date = calendar.date(from: DateComponents(year: year, month: month, day: day, hour: hour, minute: minute, second: second))!
        return Int64(date.timeIntervalSince1970)
    }

    private func assertSane(_ result: GGRegDateResult?, now: Int32? = nil, file: StaticString = #filePath, line: UInt = #line) {
        guard let result = result else {
            XCTFail("no result", file: file, line: line)
            return
        }
        let limit = Int64(max(now ?? self.now, Int32(GGRegDateAnchors.dataEnd)))
        XCTAssertLessThanOrEqual(result.range.from, result.point, file: file, line: line)
        XCTAssertLessThanOrEqual(result.point, result.range.to, file: file, line: line)
        XCTAssertGreaterThanOrEqual(Int64(result.range.from), GGRegDateAnchors.launch, file: file, line: line)
        XCTAssertLessThanOrEqual(Int64(result.range.to), limit, file: file, line: line)
        XCTAssertEqual(result.dataVersion, GGRegDateResolver.dataVersion, file: file, line: line)
    }

    // MARK: - The generated table

    func testTableIsMonotoneAndConsistent() {
        let ids = GGRegDateAnchors.ids
        let points = GGRegDateAnchors.points
        let lows = GGRegDateAnchors.lows
        let highs = GGRegDateAnchors.highs
        XCTAssertGreaterThan(ids.count, 50)
        XCTAssertEqual(points.count, ids.count)
        XCTAssertEqual(lows.count, ids.count)
        XCTAssertEqual(highs.count, ids.count)
        XCTAssertEqual(ids.first, 0)
        for i in 0 ..< ids.count {
            XCTAssertLessThanOrEqual(lows[i], points[i])
            XCTAssertLessThanOrEqual(points[i], highs[i])
            XCTAssertGreaterThanOrEqual(Int64(lows[i]), GGRegDateAnchors.launch)
            if i > 0 {
                XCTAssertGreaterThan(ids[i], ids[i - 1], "ids grow at \(i)")
                XCTAssertGreaterThanOrEqual(points[i], points[i - 1], "points never go back at \(i)")
                XCTAssertGreaterThanOrEqual(lows[i], lows[i - 1], "low edge never goes back at \(i)")
                XCTAssertGreaterThanOrEqual(highs[i], highs[i - 1], "high edge never goes back at \(i)")
            }
        }
        XCTAssertGreaterThan(GGRegDateAnchors.idsPerSecond, 0)
        XCTAssertGreaterThanOrEqual(GGRegDateAnchors.dataEnd, Int64(points[points.count - 1]))
        XCTAssertEqual(GGRegDateResolver.dataVersion, GGRegDateAnchors.dataVersion)
        XCTAssertEqual(GGRegDateEstimateFixture.dataVersion, GGRegDateAnchors.dataVersion, "fixture regenerated with the table")
        XCTAssertGreaterThanOrEqual(GGRegDateResolver.dataVersion, 1)
    }

    // MARK: - The same function as generate.py

    func testSwiftMatchesThePythonModel() {
        let fixture = GGRegDateEstimateFixture.self
        XCTAssertEqual(fixture.probeIds.count, fixture.probePoints.count)
        var worst: Int64 = 0
        for i in 0 ..< fixture.probeIds.count {
            guard let result = GGRegDateResolver.estimate(userId: fixture.probeIds[i], now: now) else {
                XCTFail("no estimate for \(fixture.probeIds[i])")
                continue
            }
            worst = max(worst, abs(Int64(result.point) - fixture.probePoints[i]))
            worst = max(worst, abs(Int64(result.range.from) - fixture.probeLows[i]))
            worst = max(worst, abs(Int64(result.range.to) - fixture.probeHighs[i]))
        }
        XCTAssertLessThanOrEqual(worst, 2, "Swift and Python disagree by \(worst) s")
    }

    func testInSampleCoverageAndError() {
        let fixture = GGRegDateEstimateFixture.self
        var inside = 0
        var errors: [Int64] = []
        for i in 0 ..< fixture.observedIds.count {
            guard let result = GGRegDateResolver.estimate(userId: fixture.observedIds[i], now: now) else {
                XCTFail("no estimate for \(fixture.observedIds[i])")
                continue
            }
            let mid = (fixture.observedFrom[i] + fixture.observedTo[i]) / 2
            if Int64(result.range.from) <= mid && mid <= Int64(result.range.to) {
                inside += 1
            }
            let point = Int64(result.point)
            let error = point < fixture.observedFrom[i] ? fixture.observedFrom[i] - point : max(0, point - fixture.observedTo[i])
            errors.append(error / day)
        }
        errors.sort()
        let coverage = Double(inside) / Double(fixture.observedIds.count)
        let median = errors[errors.count / 2]
        let p90 = errors[errors.count * 9 / 10]
        print("GGRegDate in-sample: \(fixture.observedIds.count) observations, \(String(format: "%.1f", coverage * 100))% inside the range, median error \(median) d, p90 \(p90) d")
        XCTAssertGreaterThan(coverage, 0.9)
        XCTAssertLessThan(median, 45)
        XCTAssertLessThan(p90, 150)
    }

    // MARK: - Edges of the ID space

    func testInvalidAndReservedIds() {
        XCTAssertNil(GGRegDateResolver.estimate(userId: 0, now: now))
        XCTAssertNil(GGRegDateResolver.estimate(userId: -5, now: now))
        XCTAssertNil(GGRegDateResolver.estimate(userId: Int64.min, now: now))
        XCTAssertNil(GGRegDateResolver.estimate(userId: 777000, now: now))
        XCTAssertNil(GGRegDateResolver.estimate(userId: 489000, now: now))
        XCTAssertNil(GGRegDateResolver.resolve(GGRegDateEvidence(userId: -1), now: now))
        XCTAssertNil(GGRegDateResolver.resolve(GGRegDateEvidence(userId: 333000), now: now))
    }

    func testSmallIdsStartAtTheLaunch() {
        let result = GGRegDateResolver.estimate(userId: 1, now: now)
        assertSane(result)
        XCTAssertLessThanOrEqual(Int64(result!.range.from), GGRegDateAnchors.launch + day)
        XCTAssertLessThan(Int64(result!.range.to), utc(2014, 6, 1), "an ID of 1 is from 2013")
    }

    func testIdsAboveTheLastAnchor() {
        let lastId = GGRegDateAnchors.ids[GGRegDateAnchors.ids.count - 1]
        let last = GGRegDateAnchors.ids.count - 1
        let lastPoint = Int64(GGRegDateAnchors.points[last])
        let lastLow = Int64(GGRegDateAnchors.lows[last])
        let band = Int64(GGRegDateAnchors.highs[last]) - lastLow
        let later = now + Int32(400 * day)
        for userId in [lastId, lastId + 1, lastId + 50_000_000, lastId + 2_000_000_000, Int64.max] {
            let result = GGRegDateResolver.estimate(userId: userId, now: later)
            assertSane(result, now: later)
            XCTAssertEqual(result!.range.to, later, "newer than every anchor: up to now")
            XCTAssertGreaterThanOrEqual(Int64(result!.point), lastPoint)
            XCTAssertGreaterThanOrEqual(Int64(result!.range.from), lastLow, "never before the last low edge")
            XCTAssertGreaterThanOrEqual(Int64(result!.range.to - result!.range.from), band, "never narrower than the last band")
            XCTAssertEqual(result!.precision, GGRegDateResolver.precision(width: Int64(result!.range.to - result!.range.from)))
        }
        // At the data's end the range of the newest ID is the last node's band or wider.
        let atEnd = GGRegDateResolver.estimate(userId: lastId + 1, now: now)!
        XCTAssertEqual(Int64(atEnd.range.to), GGRegDateAnchors.dataEnd)
        // The range widens with the ID, never narrows.
        let a = GGRegDateResolver.estimate(userId: lastId + 10_000_000, now: later)!
        let b = GGRegDateResolver.estimate(userId: lastId + 300_000_000, now: later)!
        XCTAssertLessThanOrEqual(a.range.from, b.range.from)
        XCTAssertLessThanOrEqual(a.point, b.point)
        // The point never passes now.
        let far = GGRegDateResolver.estimate(userId: Int64.max, now: later)!
        XCTAssertEqual(far.point, later)
    }

    func testTopOfTheTableAgesWithTheClock() {
        // Accounts made after the data still get IDs a little below the newest one: as the clock
        // moves on, the high edge there follows it, deeper IDs are not touched.
        let lastId = GGRegDateAnchors.ids[GGRegDateAnchors.ids.count - 1]
        let later = now + Int32(300 * day)
        let nearTop = lastId - 100_000_000
        let atBuild = GGRegDateResolver.estimate(userId: nearTop, now: now)!
        let aged = GGRegDateResolver.estimate(userId: nearTop, now: later)!
        XCTAssertGreaterThan(aged.range.to, atBuild.range.to)
        XCTAssertLessThanOrEqual(aged.range.to, later)
        XCTAssertEqual(aged.range.from, atBuild.range.from)
        XCTAssertEqual(aged.point, atBuild.point)
        let deep = lastId - 1_500_000_000
        XCTAssertEqual(GGRegDateResolver.estimate(userId: deep, now: now), GGRegDateResolver.estimate(userId: deep, now: later))
        // The high edge still grows with the ID across the top.
        var previous: Int32 = 0
        for step in stride(from: Int64(800_000_000), through: 0, by: -50_000_000) {
            let result = GGRegDateResolver.estimate(userId: lastId - step, now: later)!
            XCTAssertGreaterThanOrEqual(result.range.to, previous)
            previous = result.range.to
        }
    }

    func testEstimateIsMonotoneInTheId() {
        var previous: GGRegDateResult?
        var userId: Int64 = 1
        while userId < 12_000_000_000 {
            if GGRegDateResolver.isReserved(userId) {
                userId += 1
                continue
            }
            let result = GGRegDateResolver.estimate(userId: userId, now: now)
            assertSane(result)
            if let previous = previous, let result = result {
                XCTAssertGreaterThanOrEqual(result.point, previous.point, "point at \(userId)")
                XCTAssertGreaterThanOrEqual(result.range.from, previous.range.from, "from at \(userId)")
            }
            previous = result
            userId = userId + userId / 37 + 1
        }
    }

    func testKnownAccounts() {
        // Observations from Data/anchors.csv that every table agrees on.
        let cases: [(Int64, Int64)] = [
            (103151531, utc(2015, 6, 3)),
            (369669043, utc(2017, 3, 31)),
            (1974255900, utc(2021, 10, 12)),
            (5869015726, utc(2023, 1, 21)),
            (8874594977, utc(2026, 6, 17)),
        ]
        for (userId, date) in cases {
            let result = GGRegDateResolver.estimate(userId: userId, now: now)!
            XCTAssertLessThanOrEqual(Int64(result.range.from), date, "\(userId)")
            XCTAssertGreaterThanOrEqual(Int64(result.range.to), date, "\(userId)")
        }
        // Service bots existed by the day their feature launched (Data/anchors.csv, kind upper).
        let bounds: [(Int64, Int64)] = [
            (93372553, utc(2015, 6, 24)),
            (1087968824, utc(2020, 9, 30)),
            (1271266957, utc(2020, 9, 30)),
        ]
        for (userId, date) in bounds {
            let result = GGRegDateResolver.estimate(userId: userId, now: now)!
            XCTAssertLessThanOrEqual(Int64(result.range.from), date, "\(userId)")
        }
    }

    func testDeviceClockBehindTheDataIsIgnored() {
        let ok = GGRegDateResolver.estimate(userId: 8_000_000_000, now: now)
        let broken = GGRegDateResolver.estimate(userId: 8_000_000_000, now: 0)
        XCTAssertEqual(ok, broken)
        assertSane(broken)
        let telegram = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 1, telegramMonth: "03.2016"), now: 0)
        XCTAssertEqual(telegram?.source, .telegram)
    }

    // MARK: - Telegram's month

    func testTelegramMonth() {
        let result = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 5_000_000_000, telegramMonth: "03.2016"), now: now)!
        XCTAssertEqual(result.source, .telegram)
        XCTAssertEqual(result.precision, .month)
        XCTAssertFalse(result.isNarrowed)
        XCTAssertEqual(Int64(result.range.from), utc(2016, 3, 1))
        XCTAssertEqual(Int64(result.range.to), utc(2016, 3, 31, 23, 59, 59))
        XCTAssertTrue(result.range.from <= result.point && result.point <= result.range.to)

        let december = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 7, telegramMonth: "12.2020"), now: now)!
        XCTAssertEqual(Int64(december.range.from), utc(2020, 12, 1))
        XCTAssertEqual(Int64(december.range.to), utc(2020, 12, 31, 23, 59, 59))
        let february = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 7, telegramMonth: "2.2024"), now: now)!
        XCTAssertEqual(Int64(february.range.to), utc(2024, 2, 29, 23, 59, 59), "leap year")
        let padded = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 7, telegramMonth: " 09.2019 "), now: now)!
        XCTAssertEqual(Int64(padded.range.from), utc(2019, 9, 1))
    }

    func testTelegramMonthBeatsEverythingElse() {
        // The month contradicts the table, the remote answer and the evidence: Telegram wins.
        let evidence = GGRegDateEvidence(
            userId: 103151531,
            telegramMonth: "01.2014",
            existedAt: Int32(utc(2013, 9, 1)),
            notBefore: Int32(utc(2016, 1, 1)),
            remote: GGRegDateRange(from: Int32(utc(2018, 1, 1)), to: Int32(utc(2018, 2, 1)))
        )
        let result = GGRegDateResolver.resolve(evidence, now: now)!
        XCTAssertEqual(result.source, .telegram)
        XCTAssertEqual(Int64(result.range.from), utc(2014, 1, 1))
        XCTAssertEqual(Int64(result.range.to), utc(2014, 1, 31, 23, 59, 59))
    }

    func testTelegramMonthOfTheCurrentMonthStopsAtNow() {
        let later = Int32(utc(2027, 3, 10))
        let result = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 9_500_000_000, telegramMonth: "03.2027"), now: later)!
        XCTAssertEqual(Int64(result.range.from), utc(2027, 3, 1))
        XCTAssertEqual(result.range.to, later)
    }

    func testBrokenTelegramMonthFallsBackToTheEstimate() {
        let estimate = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 400_000_000), now: now)!
        for broken in ["", " ", "13.2016", "00.2016", "0.2016", "03-2016", "03.16", "03.20166", "a.2016",
                       "03.2016.1", ".2016", "03.", "003.2016", "03 .2016", "03.2012", "03.2099", "١٠.٢٠١٦"] {
            let result = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 400_000_000, telegramMonth: broken), now: now)
            XCTAssertEqual(result, estimate, "«\(broken)»")
        }
    }

    // MARK: - Remote answers

    func testRemoteAnswer() {
        let from = Int32(utc(2017, 2, 1))
        let to = Int32(utc(2017, 4, 1))
        let result = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 400_000_000, remote: GGRegDateRange(from: from, to: to)), now: now)!
        XCTAssertEqual(result.source, .remote)
        XCTAssertEqual(result.range, GGRegDateRange(from: from, to: to))
        XCTAssertEqual(Int64(result.point), (Int64(from) + Int64(to)) / 2)
        XCTAssertEqual(result.precision, .month)
        XCTAssertFalse(result.isNarrowed)

        // Narrowed by evidence like the estimate is.
        let narrowed = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 400_000_000, existedAt: Int32(utc(2017, 3, 1)), remote: GGRegDateRange(from: from, to: to)), now: now)!
        XCTAssertEqual(narrowed.source, .remote)
        XCTAssertTrue(narrowed.isNarrowed)
        XCTAssertEqual(Int64(narrowed.range.to), utc(2017, 3, 1))
    }

    func testBrokenRemoteAnswerFallsBackToTheEstimate() {
        let estimate = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 400_000_000), now: now)!
        let reversed = GGRegDateRange(from: Int32(utc(2017, 4, 1)), to: Int32(utc(2017, 2, 1)))
        let future = GGRegDateRange(from: now + 1000, to: now + 2000)
        let prehistoric = GGRegDateRange(from: 0, to: 1000)
        for remote in [reversed, future, prehistoric] {
            XCTAssertEqual(GGRegDateResolver.resolve(GGRegDateEvidence(userId: 400_000_000, remote: remote), now: now), estimate)
        }
        // Partly before the launch: cut at the launch, still remote.
        let early = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 1000, remote: GGRegDateRange(from: 0, to: Int32(utc(2013, 10, 1)))), now: now)!
        XCTAssertEqual(early.source, .remote)
        XCTAssertEqual(Int64(early.range.from), GGRegDateAnchors.launch)
    }

    // MARK: - Evidence

    func testExistedAtNarrowsFromAbove() {
        let base = GGRegDateResolver.estimate(userId: 7_500_000_000, now: now)!
        let existedAt = base.range.from + (base.range.to - base.range.from) / 3
        let result = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 7_500_000_000, existedAt: existedAt), now: now)!
        XCTAssertEqual(result.source, .estimate)
        XCTAssertTrue(result.isNarrowed)
        XCTAssertEqual(result.range.from, base.range.from)
        XCTAssertEqual(result.range.to, existedAt)
        XCTAssertLessThanOrEqual(result.point, existedAt)
        assertSane(result)
    }

    func testNotBeforeNarrowsFromBelow() {
        let base = GGRegDateResolver.estimate(userId: 7_500_000_000, now: now)!
        let notBefore = base.range.to - (base.range.to - base.range.from) / 4
        let result = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 7_500_000_000, notBefore: notBefore), now: now)!
        XCTAssertTrue(result.isNarrowed)
        XCTAssertEqual(result.range.from, notBefore)
        XCTAssertEqual(result.range.to, base.range.to)
        XCTAssertGreaterThanOrEqual(result.point, notBefore)
    }

    func testBothBoundsGiveADay() {
        let base = GGRegDateResolver.estimate(userId: 7_500_000_000, now: now)!
        let a = base.range.from + 10 * Int32(day)
        let result = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 7_500_000_000, existedAt: a + Int32(day), notBefore: a), now: now)!
        XCTAssertEqual(result.range, GGRegDateRange(from: a, to: a + Int32(day)))
        XCTAssertEqual(result.precision, .day)
    }

    func testEvidenceOlderThanTheTableWins() {
        // The oldest photo is from before the table's lower edge: the table is wrong for this one.
        let base = GGRegDateResolver.estimate(userId: 7_500_000_000, now: now)!
        let existedAt = base.range.from - Int32(200 * day)
        let result = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 7_500_000_000, existedAt: existedAt), now: now)!
        XCTAssertTrue(result.isNarrowed)
        XCTAssertEqual(result.range.to, existedAt)
        XCTAssertEqual(result.point, existedAt)
        XCTAssertEqual(result.range.to - result.range.from, base.range.to - base.range.from, "same width, ending at the evidence")
        assertSane(result)
    }

    func testLowerBoundNewerThanTheTableWins() {
        let base = GGRegDateResolver.estimate(userId: 400_000_000, now: now)!
        let notBefore = base.range.to + Int32(100 * day)
        let result = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 400_000_000, notBefore: notBefore), now: now)!
        XCTAssertEqual(result.range.from, notBefore)
        XCTAssertEqual(result.point, notBefore)
        XCTAssertGreaterThan(result.range.to, notBefore)
        assertSane(result)
    }

    func testContradictoryOrInvalidEvidence() {
        let base = GGRegDateResolver.estimate(userId: 7_500_000_000, now: now)!
        // notBefore after existedAt: the observed existence stays, the lower bound goes.
        let existedAt = base.range.from + (base.range.to - base.range.from) / 2
        let both = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 7_500_000_000, existedAt: existedAt, notBefore: existedAt + Int32(30 * day)), now: now)!
        XCTAssertEqual(both.range.from, base.range.from)
        XCTAssertEqual(both.range.to, existedAt)
        // In the future or before Telegram: ignored.
        for evidence in [
            GGRegDateEvidence(userId: 7_500_000_000, existedAt: now + Int32(day)),
            GGRegDateEvidence(userId: 7_500_000_000, existedAt: 1000),
            GGRegDateEvidence(userId: 7_500_000_000, notBefore: now + Int32(day)),
            GGRegDateEvidence(userId: 7_500_000_000, notBefore: Int32.min),
            GGRegDateEvidence(userId: 7_500_000_000, existedAt: Int32.max, notBefore: Int32.min),
        ] {
            let result = GGRegDateResolver.resolve(evidence, now: now)!
            XCTAssertEqual(result, base)
            XCTAssertFalse(result.isNarrowed)
        }
        // Evidence that does not cut the range changes nothing.
        let loose = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 7_500_000_000, existedAt: base.range.to, notBefore: base.range.from), now: now)!
        XCTAssertEqual(loose, base)
    }

    func testPrecisionFollowsTheWidth() {
        XCTAssertEqual(GGRegDateResolver.precision(width: 0), .day)
        XCTAssertEqual(GGRegDateResolver.precision(width: 2 * day), .day)
        XCTAssertEqual(GGRegDateResolver.precision(width: 2 * day + 1), .month)
        XCTAssertEqual(GGRegDateResolver.precision(width: 183 * day), .month)
        XCTAssertEqual(GGRegDateResolver.precision(width: 183 * day + 1), .year)
    }

    func testMonthStartArithmetic() {
        XCTAssertEqual(GGRegDateResolver.monthStart(year: 1970, month: 1), 0)
        XCTAssertEqual(GGRegDateResolver.monthStart(year: 2013, month: 8), utc(2013, 8, 1))
        XCTAssertEqual(GGRegDateResolver.monthStart(year: 2024, month: 3), utc(2024, 3, 1))
        XCTAssertEqual(GGRegDateResolver.monthStart(year: 2100, month: 3), utc(2100, 3, 1))
        XCTAssertEqual(GGRegDateResolver.monthStart(year: 2000, month: 2), utc(2000, 2, 1))
    }

    func testResultsSurviveCoding() throws {
        let result = GGRegDateResolver.resolve(GGRegDateEvidence(userId: 6_000_000_000, existedAt: Int32(utc(2023, 6, 1))), now: now)!
        let data = try JSONEncoder().encode(result)
        XCTAssertEqual(try JSONDecoder().decode(GGRegDateResult.self, from: data), result)
    }
}
